; macro.asm -- chapter 15: a macro and a subroutine
; generated by gen15.py
        INCLUDE "msx.inc"
        OUTPUT "macro.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
; HL = HL + n eight times with a macro, and eight times with a subroutine:
; the same sum, and the bytes and T-states of each way.

        MACRO ADDHL n           ; HL = HL + n, n from 0 to 255; A is lost
        ld a, n
        add a, l
        ld l, a
        adc a, h
        sub l
        ld h, a
        ENDM

; addhla: HL = HL + A, the same five instructions once. A is lost.
addhla: add a, l
        ld l, a
        adc a, h
        sub l
        ld h, a
        ret

init:   di
        ld sp, SYS_AREA
        ld hl, 0
m0:     DUP 8, k                ; k = 0, 1 ... 7
        ADDHL 10*k+5            ; the macro: six instructions every time
        EDUP
m1:     ld (RESULTS), hl
        ld hl, 0
m2:     DUP 8, k
        ld a, 10*k+5
        call addhla             ; the subroutine: two instructions every time
        EDUP
m3:     ld (RESULTS+2), hl
stop:   jr stop
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
